function Login() {
  const { session, signIn } = useAuth(); const navigate = useNavigate(); const [error, setError] = useState(''); const [busy, setBusy] = useState(false)
  const { register, handleSubmit, formState: { errors } } = useForm<{ email: string; password: string; organization: string }>({ defaultValues: { organization: 'cdx' } })
  const submit = async (data: { email: string; password: string; organization: string }) => { setBusy(true); setError(''); try { await signIn(data); navigate('/') } catch (e) { setError(e instanceof Error ? e.message : 'Unable to sign in') } finally { setBusy(false) } }
  if (session) return <Navigate to="/" replace/>
  return <Box sx={{ minHeight: '100vh', display: 'grid', placeItems: 'center', p: 2, background: 'linear-gradient(135deg,#eef4ff,#f8fafc)' }}><Card sx={{ width: '100%', maxWidth: 430 }}><CardContent sx={{ p: { xs: 3, sm: 5 } }}><Stack spacing={3}><Box><Typography variant="h4">botq</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Human-supervised software delivery control plane</Typography></Box>{error && <Alert severity="error">{error}</Alert>}<Box component="form" onSubmit={handleSubmit(submit)}><Stack spacing={2}><TextField label="Organization" fullWidth {...register('organization', { required: true })}/><TextField label="Email" type="email" fullWidth autoComplete="username" error={Boolean(errors.email)} helperText={errors.email && 'Email is required'} {...register('email', { required: true })}/><TextField label="Password" type="password" fullWidth autoComplete="current-password" error={Boolean(errors.password)} helperText={errors.password && 'Password is required'} {...register('password', { required: true })}/><Button type="submit" variant="contained" size="large" disabled={busy}>{busy ? <CircularProgress size={22}/> : 'Sign in'}</Button></Stack></Box><Typography variant="caption" color="text.secondary">Access is organization-scoped. Your session is protected by an HttpOnly cookie.</Typography></Stack></CardContent></Card></Box>
}

function Guard({ children }: { children: ReactNode }) { const { session, loading } = useAuth(); if (loading) return <Box sx={{ display: 'grid', placeItems: 'center', minHeight: '100vh' }}><CircularProgress/></Box>; return session ? <>{children}</> : <Navigate to="/login" replace/> }

function ProjectSelect() { const [params, setParams] = useSearchParams(); const query = useQuery({ queryKey: ['projects'], queryFn: projects }); const selected = params.get('project') ?? ''; return <Select value={selected} displayEmpty size="small" onChange={(event) => { const next = new URLSearchParams(params); next.set('project', event.target.value); setParams(next) }} sx={{ minWidth: 190, display: { xs: 'none', sm: 'flex' } }}><MenuItem value=""><em>Select project</em></MenuItem>{(query.data ?? []).map((project) => <MenuItem value={project.id} key={project.id}>{project.key} · {project.name}</MenuItem>)}</Select> }
function useProjectContext() { const [params] = useSearchParams(); const projectId = params.get('project') ?? ''; const query = useQuery({ queryKey: ['projects'], queryFn: projects }); return { projectId, project: query.data?.find((item) => item.id === projectId), projects: query.data ?? [], loading: query.isLoading } }
function ProjectRequired({ children }: { children: (projectId: string) => ReactNode }) { const { projectId, projects: available } = useProjectContext(); if (!projectId) return <Alert severity="info" action={<Button size="small" href="/projects">Choose a project</Button>}>Choose a project from the top bar to work with project-scoped delivery records.</Alert>; if (!available.some((project) => project.id === projectId)) return <Alert severity="warning">The selected project is unavailable or you no longer have access.</Alert>; return <>{children(projectId)}</> }

function ProjectsPage() { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ['projects'], queryFn: projects }); const [dialog, setDialog] = useState(false); const [error, setError] = useState(''); const mutation = useMutation({ mutationFn: createProject, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['projects'] }); setDialog(false) } }); const { register, handleSubmit, reset, formState: { errors } } = useForm<{ name: string; key: string; description: string; default_branch: string }>({ defaultValues: { default_branch: 'main' } }); const submit = async (data: { name: string; key: string; description: string; default_branch: string }) => { setError(''); try { await mutation.mutateAsync(data); reset() } catch (e) { setError(e instanceof Error ? e.message : 'Unable to create project') } }; return <><PageHeader title="Projects" description="Create and manage the delivery workspaces in your organization." action={<Button variant="contained" startIcon={<Add/>} onClick={() => setDialog(true)}>New project</Button>}/>{query.isLoading ? <CircularProgress/> : <Stack spacing={2}>{(query.data ?? []).length === 0 && <Paper sx={{ p: 4 }}><Typography variant="h6">No projects yet</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Create the first project to unlock requirements, traceability, gates, and release workflows.</Typography></Paper>}{(query.data ?? []).map((project) => <Card key={project.id}><CardContent><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}><Box sx={{ flex: 1 }}><Stack direction="row" spacing={1} alignItems="center"><Typography variant="h6">{project.name}</Typography><Chip label={project.lifecycle_state} size="small" color="primary" variant="outlined"/></Stack><Typography color="text.secondary" sx={{ mt: .5 }}>{project.key} · {project.description || 'No description'}</Typography></Box><Button href={`/?project=${project.id}`} variant="outlined">Open workspace</Button></Stack></CardContent></Card>)}</Stack>}<Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="sm"><DialogTitle>Create project</DialogTitle><Box component="form" onSubmit={handleSubmit(submit)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Name" fullWidth error={Boolean(errors.name)} helperText={errors.name && 'Name is required'} {...register('name', { required: true })}/><TextField label="Key" placeholder="payments" fullWidth error={Boolean(errors.key)} helperText={errors.key ? 'Use lowercase letters, numbers, - or _' : '2–64 characters'} {...register('key', { required: true, pattern: /^[a-z0-9_-]{2,64}$/ })}/><TextField label="Description" fullWidth multiline minRows={2} {...register('description')}/><TextField label="Default branch" fullWidth {...register('default_branch')}/></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained" disabled={mutation.isPending}>{mutation.isPending ? <CircularProgress size={18}/> : 'Create project'}</Button></DialogActions></Box></Dialog></> }

function RequirementsPage() { return <ProjectRequired>{(projectId) => <RequirementsWorkspace projectId={projectId}/>}</ProjectRequired> }
const architectureTemplate = '{\n  "context": "",\n  "components": [],\n  "data": [],\n  "integrations": [],\n  "deployment": [],\n  "security": [],\n  "operations": [],\n  "threats": [],\n  "failures": []\n}'
function ArchitecturePage() { return <ProjectRequired>{(projectId) => <ArchitectureWorkspace projectId={projectId}/>}</ProjectRequired> }
function ArchitectureWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const packageQuery = useQuery({ queryKey: ['architecture', projectId], queryFn: () => architecturePackages(projectId) }); const baselineQuery = useQuery({ queryKey: ['baselines', projectId], queryFn: () => baselines(projectId) }); const [dialog, setDialog] = useState(false); const [error, setError] = useState(''); const mutation = useMutation({ mutationFn: createArchitecture, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['architecture', projectId] }); setDialog(false) } }); const action = useMutation({ mutationFn: ({ id, kind }: { id: string; kind: 'submit' | 'approve' | 'request-changes' }) => architectureAction(id, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['architecture', projectId] }) }); const { register, handleSubmit, reset, formState: { errors } } = useForm<{ title: string; source_baseline_id: string; content: string }>({ defaultValues: { content: architectureTemplate } }); const submit = async (data: { title: string; source_baseline_id: string; content: string }) => { try { await mutation.mutateAsync({ ...data, project_id: projectId, content: JSON.parse(data.content) }); reset({ content: architectureTemplate }); } catch (e) { setError(e instanceof SyntaxError ? 'Architecture content must be valid JSON.' : e instanceof Error ? e.message : 'Unable to create architecture') } }; return <><PageHeader title="Architecture & ADRs" description="Turn approved requirements into reviewable architecture decisions and technical boundaries." action={<Button variant="contained" startIcon={<Add/>} onClick={() => setDialog(true)}>New architecture</Button>}/><Stack spacing={2}>{(packageQuery.data ?? []).map((item) => <Card key={item.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Typography variant="h6">{item.title}</Typography><Typography variant="body2" color="text.secondary">Version {item.current_version} · {item.status} · hash {item.content_hash ?? 'available on detail'}</Typography></Box><Stack direction="row" spacing={1}><Button size="small" variant="outlined" disabled={action.isPending || item.status !== 'draft'} onClick={() => action.mutate({ id: item.id, kind: 'submit' })}>Submit</Button><Button size="small" color="success" disabled={action.isPending || item.status !== 'submitted'} onClick={() => action.mutate({ id: item.id, kind: 'approve' })}>Approve</Button></Stack></Stack></CardContent></Card>)}{!packageQuery.isLoading && !(packageQuery.data ?? []).length && <Paper sx={{ p: 4 }}><Typography variant="h6">No architecture packages</Typography><Typography color="text.secondary">Approve a requirements baseline before creating architecture.</Typography></Paper>}</Stack><Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="md"><DialogTitle>New architecture package</DialogTitle><Box component="form" onSubmit={handleSubmit(submit)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Title" fullWidth error={Boolean(errors.title)} {...register('title', { required: true })}/><TextField select label="Approved requirement baseline" fullWidth error={Boolean(errors.source_baseline_id)} {...register('source_baseline_id', { required: true })}><MenuItem value="">Select baseline</MenuItem>{(baselineQuery.data ?? []).filter((item) => item.status === 'approved').map((item) => <MenuItem value={item.id} key={item.id}>{item.title}</MenuItem>)}</TextField><TextField label="Architecture content (JSON)" fullWidth multiline minRows={14} {...register('content', { required: true })}/></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained" disabled={mutation.isPending}>Create architecture</Button></DialogActions></Box></Dialog></> }
function PlanningPage() { return <ProjectRequired>{(projectId) => <PlanningWorkspace projectId={projectId}/>}</ProjectRequired> }
function PlanningWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const planQuery = useQuery({ queryKey: ['plans', projectId], queryFn: () => plans(projectId) }); const architectureQuery = useQuery({ queryKey: ['architecture', projectId], queryFn: () => architecturePackages(projectId) }); const runQuery = useQuery({ queryKey: ['agent-runs', projectId], queryFn: () => agentRuns(projectId) }); const [dialog, setDialog] = useState(false); const [error, setError] = useState(''); const mutation = useMutation({ mutationFn: createPlan, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['plans', projectId] }); setDialog(false) } }); const action = useMutation({ mutationFn: ({ id, kind }: { id: string; kind: 'submit' | 'approve' | 'request-changes' }) => planAction(id, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['plans', projectId] }) }); const runAction = useMutation({ mutationFn: ({ id, kind }: { id: string; kind: 'start' | 'pause' | 'cancel' }) => agentRunAction(id, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['agent-runs', projectId] }) }); const { register, handleSubmit, reset, formState: { errors } } = useForm<{ title: string; source_architecture_id: string; content: string }>({ defaultValues: { content: '{\n  "steps": [],\n  "environment_manifest": {},\n  "budget": {},\n  "permissions": { "tools": [], "paths": [] },\n  "escalation_rules": [],\n  "feasibility": {}\n}' } }); const submit = async (data: { title: string; source_architecture_id: string; content: string }) => { try { await mutation.mutateAsync({ ...data, project_id: projectId, content: JSON.parse(data.content) }); reset() } catch (e) { setError(e instanceof SyntaxError ? 'Plan content must be valid JSON.' : e instanceof Error ? e.message : 'Unable to create plan') } }; return <><PageHeader title="Plans & agent runs" description="Review approved architecture, create constrained technical plans, and supervise execution." action={<Button variant="contained" startIcon={<Add/>} onClick={() => setDialog(true)}>New plan</Button>}/><Typography variant="h6" sx={{ mb: 1 }}>Technical plans</Typography><Stack spacing={2} sx={{ mb: 4 }}>{(planQuery.data ?? []).map((item) => <Card key={item.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Typography variant="h6">{item.title}</Typography><Typography variant="body2" color="text.secondary">Version {item.current_version} · {item.status} · hash {item.content_hash ?? 'available on detail'}</Typography></Box><Stack direction="row" spacing={1}><Button size="small" variant="outlined" disabled={action.isPending || item.status !== 'draft'} onClick={() => action.mutate({ id: item.id, kind: 'submit' })}>Submit</Button><Button size="small" color="success" disabled={action.isPending || item.status !== 'submitted'} onClick={() => action.mutate({ id: item.id, kind: 'approve' })}>Approve</Button></Stack></Stack></CardContent></Card>)}</Stack><Typography variant="h6" sx={{ mb: 1 }}>Agent runs</Typography><Stack spacing={2}>{(runQuery.data ?? []).map((run) => <Card key={run.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Typography fontWeight={600}>{run.objective}</Typography><Typography variant="body2" color="text.secondary">{run.status} · {run.allowed_tools.length} allowed tools · {run.writable_paths.length} writable paths</Typography></Box>{run.status === 'queued' || run.status === 'paused' ? <Button size="small" variant="contained" onClick={() => runAction.mutate({ id: run.id, kind: 'start' })}>Start</Button> : run.status === 'running' ? <Button size="small" variant="outlined" onClick={() => runAction.mutate({ id: run.id, kind: 'pause' })}>Pause</Button> : null}{['queued', 'running', 'paused'].includes(run.status) && <Button size="small" color="error" onClick={() => runAction.mutate({ id: run.id, kind: 'cancel' })}>Cancel</Button>}</Stack></CardContent></Card>)}{!runQuery.isLoading && !(runQuery.data ?? []).length && <Paper sx={{ p: 3 }}><Typography color="text.secondary">No agent runs. Create one after approving a technical plan.</Typography></Paper>}</Stack><Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="md"><DialogTitle>New technical plan</DialogTitle><Box component="form" onSubmit={handleSubmit(submit)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Title" fullWidth error={Boolean(errors.title)} {...register('title', { required: true })}/><TextField select label="Approved architecture" fullWidth {...register('source_architecture_id', { required: true })}><MenuItem value="">Select architecture</MenuItem>{(architectureQuery.data ?? []).filter((item) => item.status === 'approved').map((item) => <MenuItem key={item.id} value={item.id}>{item.title}</MenuItem>)}</TextField><TextField label="Plan content (JSON)" fullWidth multiline minRows={14} {...register('content', { required: true })}/></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained" disabled={mutation.isPending}>Create plan</Button></DialogActions></Box></Dialog></> }

function DesignPage() { return <ProjectRequired>{(projectId) => <DesignWorkspace projectId={projectId}/>}</ProjectRequired> }
function DesignWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const mockupQuery = useQuery({ queryKey: ['mockups', projectId], queryFn: () => mockups(projectId) }); const previewQuery = useQuery({ queryKey: ['previews', projectId], queryFn: () => previews(projectId) }); const defectQuery = useQuery({ queryKey: ['defects', projectId], queryFn: () => defects(projectId) }); const architectureQuery = useQuery({ queryKey: ['architecture', projectId], queryFn: () => architecturePackages(projectId) }); const [mockupDialog, setMockupDialog] = useState(false); const [defectDialog, setDefectDialog] = useState(false); const [error, setError] = useState(''); const mockupMutation = useMutation({ mutationFn: createMockup, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['mockups', projectId] }); setMockupDialog(false) } }); const defectMutation = useMutation({ mutationFn: createDefect, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['defects', projectId] }); setDefectDialog(false) } }); const mockupActionMutation = useMutation({ mutationFn: ({ id, action }: { id: string; action: 'submit' | 'approve' }) => mockupAction(id, action), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['mockups', projectId] }) }); const revokeMutation = useMutation({ mutationFn: revokePreview, onSuccess: () => queryClient.invalidateQueries({ queryKey: ['previews', projectId] }) }); const mockupForm = useForm<{ title: string; source_architecture_id: string; file_id: string; file_url: string; preview_url: string }>(); const defectForm = useForm<{ title: string; severity: string; expected: string; actual: string; reproduction: string }>(); const submitMockup = async (data: { title: string; source_architecture_id: string; file_id: string; file_url: string; preview_url: string }) => { try { await mockupMutation.mutateAsync({ ...data, project_id: projectId, provider: 'penpot', content: { pages: [], nodes: [] } }) } catch (e) { setError(e instanceof Error ? e.message : 'Unable to create mockup') } }; const submitDefect = async (data: { title: string; severity: string; expected: string; actual: string; reproduction: string }) => { try { await defectMutation.mutateAsync({ ...data, project_id: projectId }) } catch (e) { setError(e instanceof Error ? e.message : 'Unable to create defect') } }; return <><PageHeader title="Design & acceptance" description="Connect approved architecture to design references, previews, acceptance, and defects." action={<Stack direction="row" spacing={1}><Button variant="outlined" onClick={() => setDefectDialog(true)}>Report defect</Button><Button variant="contained" startIcon={<Add/>} onClick={() => setMockupDialog(true)}>New mockup</Button></Stack>}/><Typography variant="h6" sx={{ mb: 1 }}>Mockups</Typography><Stack spacing={2} sx={{ mb: 4 }}>{(mockupQuery.data ?? []).map((item) => <Card key={item.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Typography variant="h6">{item.title}</Typography><Typography variant="body2" color="text.secondary">{item.status} · Version {item.current_version} · {item.design_reference?.file_id}</Typography></Box><Button size="small" variant="outlined" disabled={item.status !== 'draft'} onClick={() => mockupActionMutation.mutate({ id: item.id, action: 'submit' })}>Submit</Button><Button size="small" color="success" disabled={item.status !== 'submitted'} onClick={() => mockupActionMutation.mutate({ id: item.id, action: 'approve' })}>Approve</Button></Stack></CardContent></Card>)}</Stack><Typography variant="h6" sx={{ mb: 1 }}>Previews</Typography><Stack spacing={1} sx={{ mb: 4 }}>{(previewQuery.data ?? []).map((preview) => <Card key={preview.id}><CardContent><Stack direction="row" spacing={2} alignItems="center"><Box sx={{ flex: 1 }}><Typography>{preview.environment} preview · {preview.status}</Typography><Typography variant="caption" color="text.secondary">{preview.url} · expires {preview.expires_at}</Typography></Box><Button size="small" color="error" onClick={() => revokeMutation.mutate(preview.id)} disabled={preview.status !== 'active'}>Revoke</Button></Stack></CardContent></Card>)}</Stack><Typography variant="h6" sx={{ mb: 1 }}>Defects</Typography><Stack spacing={1}>{(defectQuery.data ?? []).map((defect) => <Card key={defect.id}><CardContent><Stack direction="row" spacing={2} alignItems="center"><Chip label={defect.severity} size="small" color={defect.severity === 'critical' ? 'error' : 'default'}/><Box sx={{ flex: 1 }}><Typography>{defect.title}</Typography><Typography variant="caption" color="text.secondary">{defect.status} · expected: {defect.expected}</Typography></Box></Stack></CardContent></Card>)}</Stack><Dialog open={mockupDialog} onClose={() => setMockupDialog(false)} fullWidth maxWidth="sm"><DialogTitle>New Penpot mockup</DialogTitle><Box component="form" onSubmit={mockupForm.handleSubmit(submitMockup)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Title" fullWidth {...mockupForm.register('title', { required: true })}/><TextField select label="Approved architecture" fullWidth {...mockupForm.register('source_architecture_id', { required: true })}>{(architectureQuery.data ?? []).filter((item) => item.status === 'approved').map((item) => <MenuItem key={item.id} value={item.id}>{item.title}</MenuItem>)}</TextField><TextField label="Penpot file ID" fullWidth {...mockupForm.register('file_id', { required: true })}/><TextField label="File URL" fullWidth {...mockupForm.register('file_url')}/><TextField label="Preview URL" fullWidth {...mockupForm.register('preview_url')}/></Stack></DialogContent><DialogActions><Button onClick={() => setMockupDialog(false)}>Cancel</Button><Button type="submit" variant="contained">Create mockup</Button></DialogActions></Box></Dialog><Dialog open={defectDialog} onClose={() => setDefectDialog(false)} fullWidth maxWidth="sm"><DialogTitle>Report defect</DialogTitle><Box component="form" onSubmit={defectForm.handleSubmit(submitDefect)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}><TextField label="Title" fullWidth {...defectForm.register('title', { required: true })}/><TextField select label="Severity" fullWidth defaultValue="medium" {...defectForm.register('severity')}><MenuItem value="critical">Critical</MenuItem><MenuItem value="high">High</MenuItem><MenuItem value="medium">Medium</MenuItem><MenuItem value="low">Low</MenuItem></TextField><TextField label="Expected" fullWidth multiline {...defectForm.register('expected')}/><TextField label="Actual" fullWidth multiline {...defectForm.register('actual')}/><TextField label="Reproduction" fullWidth multiline {...defectForm.register('reproduction')}/></Stack></DialogContent><DialogActions><Button onClick={() => setDefectDialog(false)}>Cancel</Button><Button type="submit" variant="contained">Create defect</Button></DialogActions></Box></Dialog></> }
