function AcceptanceWorkspace({ projectId }: { projectId: string }) { const previewQuery = useQuery({ queryKey: ['previews', projectId], queryFn: () => previews(projectId) }); const [session, setSession] = useState<{ id: string; criteria: { key: string; label?: string }[]; status: string } | null>(null); const create = useMutation({ mutationFn: createAcceptanceSession, onSuccess: setSession }); const result = useMutation({ mutationFn: ({ key, outcome }: { key: string; outcome: string }) => recordAcceptanceResult(session!.id, { criterion_key: key, outcome, evidence: {} }) }); const complete = useMutation({ mutationFn: () => completeAcceptanceSession(session!.id, { completed_in_ui: true }), onSuccess: setSession }); const form = useForm<{ preview_id: string; criteria: string; scenario_guidance: string }>(); const start = (data: { preview_id: string; criteria: string; scenario_guidance: string }) => create.mutate({ ...data, criteria: JSON.parse(data.criteria), scenario_guidance: data.scenario_guidance.split('\n').filter(Boolean), project_id: projectId }); return <><PageHeader title="Acceptance sessions" description="Run human acceptance against an authenticated, time-bound preview." action={!session ? <Button variant="contained" onClick={() => document.getElementById('acceptance-form')?.scrollIntoView()}>Start session</Button> : undefined}/>{session ? <Card><CardContent><Stack spacing={2}><Stack direction="row" spacing={1}><Chip label={session.status}/><Typography variant="h6">Acceptance session</Typography></Stack>{session.criteria.map((criterion) => <Stack direction="row" spacing={2} alignItems="center" key={criterion.key}><Typography sx={{ flex: 1 }}>{criterion.label || criterion.key}</Typography><Button size="small" onClick={() => result.mutate({ key: criterion.key, outcome: 'pass' })}>Pass</Button><Button size="small" color="error" onClick={() => result.mutate({ key: criterion.key, outcome: 'fail' })}>Fail</Button></Stack>)}<Button variant="contained" color="success" onClick={() => complete.mutate()} disabled={complete.isPending}>Complete acceptance</Button></Stack></CardContent></Card> : <Box id="acceptance-form" component="form" onSubmit={form.handleSubmit(start)} sx={{ maxWidth: 700 }}><Stack spacing={2}><TextField select label="Active preview" fullWidth {...form.register('preview_id', { required: true })}>{(previewQuery.data ?? []).filter((item) => item.status === 'active').map((item) => <MenuItem key={item.id} value={item.id}>{item.environment} · {item.url}</MenuItem>)}</TextField><TextField label="Criteria JSON" multiline minRows={6} fullWidth defaultValue={'[{"key":"smoke","label":"Core flow works"}]'} {...form.register('criteria', { required: true })}/><TextField label="Scenario guidance" multiline minRows={3} fullWidth {...form.register('scenario_guidance')}/><Button type="submit" variant="contained">Create acceptance session</Button></Stack></Box>}</> }
