function PreviewControlWorkspace({ projectId }: { projectId: string }) { const mockupsQuery = useQuery({ queryKey: ['mockups', projectId], queryFn: () => mockups(projectId) }); const mutation = useMutation({ mutationFn: createPreview }); const form = useForm<{ mockup_id: string; commit_sha: string; expires_at: string; url: string; environment: string }>({ defaultValues: { environment: 'preview' } }); const submit = (data: { mockup_id: string; commit_sha: string; expires_at: string; url: string; environment: string }) => mutation.mutate({ ...data, access_policy: { authentication: 'required', data_class: 'synthetic' }, deploy: false }); return <><PageHeader title="Preview provisioning" description="Provision an authenticated preview with bounded expiry and non-production data policy."/><Box component="form" onSubmit={form.handleSubmit(submit)} sx={{ maxWidth: 700 }}><Stack spacing={2}><TextField select label="Approved mockup" fullWidth {...form.register('mockup_id', { required: true })}>{(mockupsQuery.data ?? []).filter((item) => item.status === 'approved').map((item) => <MenuItem key={item.id} value={item.id}>{item.title}</MenuItem>)}</TextField><TextField label="Commit SHA" fullWidth {...form.register('commit_sha', { required: true })}/><TextField label="HTTPS preview URL" fullWidth {...form.register('url', { required: true })}/><TextField label="Expires at" type="datetime-local" InputLabelProps={{ shrink: true }} fullWidth {...form.register('expires_at', { required: true })}/><Button type="submit" variant="contained" disabled={mutation.isPending}>Provision preview</Button></Stack></Box></> }
