function ChangeSetWorkspace({ projectId }: { projectId: string }) { const runs = useQuery({ queryKey: ['agent-runs', projectId], queryFn: () => agentRuns(projectId) }); const [changeSet, setChangeSet] = useState<{ id: string; status: string; diff_hash?: string; files: { path: string; action: string; content_hash: string }[]; verifications: { kind: string; status: string }[] } | null>(null); const create = useMutation({ mutationFn: ({ runId, branch, base_commit }: { runId: string; branch: string; base_commit: string }) => createChangeSet(runId, { branch, base_commit }), onSuccess: setChangeSet }); const file = useMutation({ mutationFn: (data: { path: string; action: string; diff: string }) => addChangeSetFile(changeSet!.id, data), onSuccess: setChangeSet }); const review = useMutation({ mutationFn: () => selfReviewChangeSet(changeSet!.id, { result: 'passed', summary: 'Reviewed in control plane' }), onSuccess: setChangeSet }); const verify = useMutation({ mutationFn: () => recordVerification(changeSet!.id, { kind: 'test', command: 'frontend verification', status: 'passed', result: { change_set_hash: changeSet!.diff_hash } }), onSuccess: () => setChangeSet((current) => current ? { ...current, verifications: [...current.verifications, { kind: 'test', status: 'passed' }] } : current) }); const submit = useMutation({ mutationFn: () => submitChangeSet(changeSet!.id), onSuccess: setChangeSet }); const approve = useMutation({ mutationFn: () => approveChangeSet(changeSet!.id), onSuccess: setChangeSet }); const form = useForm<{ runId: string; branch: string; base_commit: string; path: string; action: string; diff: string }>({ defaultValues: { branch: 'feature/review', action: 'modify' } }); const start = (data: { runId: string; branch: string; base_commit: string; path: string; action: string; diff: string }) => create.mutate(data); return <><PageHeader title="Change sets" description="Review generated changes as bounded, hash-linked artifacts before release."/><Stack spacing={2} sx={{ maxWidth: 900 }}><TextField select label="Agent run" fullWidth {...form.register('runId', { required: true })}>{(runs.data ?? []).filter((run) => ['running', 'paused', 'completed'].includes(run.status)).map((run) => <MenuItem key={run.id} value={run.id}>{run.objective} · {run.status}</MenuItem>)}</TextField><Stack direction="row" spacing={2}><TextField label="Branch" fullWidth {...form.register('branch', { required: true })}/><TextField label="Base commit" fullWidth {...form.register('base_commit', { required: true })}/></Stack><Button variant="contained" onClick={form.handleSubmit(start)} disabled={Boolean(changeSet)}>Create change set</Button>{changeSet && <Card><CardContent><Stack spacing={2}><Typography variant="h6">Change set · {changeSet.status}</Typography><Typography variant="caption">Hash: {changeSet.diff_hash || 'not generated until self-review'}</Typography><Stack direction="row" spacing={1}><TextField label="File path" {...form.register('path')}/><TextField select label="Action" {...form.register('action')}><MenuItem value="add">Add</MenuItem><MenuItem value="modify">Modify</MenuItem><MenuItem value="delete">Delete</MenuItem></TextField></Stack><TextField label="Diff" multiline minRows={6} fullWidth {...form.register('diff')}/><Button onClick={form.handleSubmit((data) => file.mutate(data))} disabled={changeSet.status !== 'draft'}>Add file</Button><Typography variant="body2">{changeSet.files.length} file(s) · {changeSet.verifications.length} verification(s)</Typography><Stack direction="row" spacing={1}><Button variant="outlined" onClick={() => review.mutate()} disabled={changeSet.status !== 'draft' || !changeSet.files.length}>Self-review</Button><Button variant="outlined" onClick={() => verify.mutate()} disabled={changeSet.status !== 'review'}>Record verification</Button><Button variant="outlined" onClick={() => submit.mutate()} disabled={changeSet.status !== 'review' || !changeSet.verifications.length}>Submit</Button><Button variant="contained" color="success" onClick={() => approve.mutate()} disabled={changeSet.status !== 'submitted'}>Approve</Button></Stack></Stack></CardContent></Card>}</Stack></> }
function DeploymentControlPage() { const [message, setMessage] = useState(''); const release = useMutation({ mutationFn: createRelease }); const plan = useMutation({ mutationFn: createDeploymentPlan }); const deploy = useMutation({ mutationFn: createDeployment }); const rollback = useMutation({ mutationFn: rollbackDeployment }); const form = useForm<{ change_set_id: string; version: string; commit_sha: string; release_notes: string; release_id: string; environment: string; deployment_plan_id: string }>({ defaultValues: { environment: 'staging' } }); const submitRelease = (data: { change_set_id: string; version: string; commit_sha: string; release_notes: string }) => release.mutate({ ...data }, { onSuccess: (value) => setMessage(`Release created: ${value.id}`), onError: (e) => setMessage(e instanceof Error ? e.message : 'Release creation failed') }); const submitPlan = (data: { release_id: string; environment: string }) => plan.mutate({ release_id: data.release_id, environment: data.environment, content: { prechecks: [], migrations: [], deployment_steps: [], health_checks: [], rollback_triggers: [], recovery_steps: [] } }, { onSuccess: (value) => setMessage(`Deployment plan created: ${value.id}`), onError: (e) => setMessage(e instanceof Error ? e.message : 'Plan creation failed') }); return <><PageHeader title="Deployment control" description="Create release and deployment authorization records. Production execution requires backend dual-control policy."/>{message && <Alert sx={{ mb: 2 }} severity={message.includes('failed') ? 'error' : 'info'}>{message}</Alert>}<Stack spacing={3} sx={{ maxWidth: 800 }}><Card><CardContent><Typography variant="h6">Create release</Typography><Stack component="form" onSubmit={form.handleSubmit(submitRelease)} spacing={2} sx={{ mt: 2 }}><TextField label="Approved change-set ID" fullWidth {...form.register('change_set_id', { required: true })}/><Stack direction="row" spacing={2}><TextField label="Version" fullWidth placeholder="1.2.3" {...form.register('version', { required: true })}/><TextField label="Commit SHA" fullWidth {...form.register('commit_sha', { required: true })}/></Stack><TextField label="Release notes" fullWidth multiline {...form.register('release_notes')}/><Button type="submit" variant="contained" disabled={release.isPending}>Create release</Button></Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Create deployment plan</Typography><Stack component="form" onSubmit={form.handleSubmit(submitPlan)} spacing={2} sx={{ mt: 2 }}><TextField label="Packaged release ID" fullWidth {...form.register('release_id', { required: true })}/><TextField select label="Environment" fullWidth {...form.register('environment')}><MenuItem value="staging">Staging</MenuItem><MenuItem value="production">Production</MenuItem></TextField><Button type="submit" variant="outlined" disabled={plan.isPending}>Create deployment plan</Button></Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Authorize deployment</Typography><Stack spacing={2} sx={{ mt: 2 }}><TextField label="Approved deployment-plan ID" fullWidth {...form.register('deployment_plan_id')}/><Stack direction="row" spacing={1}><Button variant="contained" color="warning" onClick={() => { if (window.confirm('Authorize and execute this deployment? This may affect a live environment.')) deploy.mutate({ deployment_plan_id: form.getValues('deployment_plan_id'), execute: true }, { onSuccess: (value) => setMessage(`Deployment queued: ${value.id}`), onError: (e) => setMessage(e instanceof Error ? e.message : 'Deployment failed') }) }}>Execute deployment</Button><TextField label="Deployment ID for rollback" {...form.register('deployment_plan_id')}/><Button color="error" onClick={() => { if (window.confirm('Rollback this deployment?')) rollback.mutate(form.getValues('deployment_plan_id'), { onSuccess: (value) => setMessage(`Rollback: ${value.status}`), onError: (e) => setMessage(e instanceof Error ? e.message : 'Rollback failed') }) }}>Rollback</Button></Stack></Stack></CardContent></Card></Stack></> }
