function ReleasesWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const releaseQuery = useQuery({ queryKey: ['releases', projectId], queryFn: () => releases(projectId) }); const planQuery = useQuery({ queryKey: ['deployment-plans'], queryFn: () => deploymentPlans() }); const deploymentQuery = useQuery({ queryKey: ['deployments'], queryFn: deployments }); const action = useMutation({ mutationFn: ({ id, kind }: { id: string; kind: 'readiness' | 'approve' | 'package' }) => releaseAction(id, kind, kind === 'readiness' ? { checks: [] } : {}), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['releases', projectId] }); queryClient.invalidateQueries({ queryKey: ['deployment-plans'] }) } }); return <><PageHeader title="Releases & deployments" description="Evaluate release readiness, package approved releases, and monitor deployment authorization."/><Typography variant="h6" sx={{ mb: 1 }}>Releases</Typography><Stack spacing={2} sx={{ mb: 4 }}>{(releaseQuery.data ?? []).map((release) => <Card key={release.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Typography variant="h6">{release.version}</Typography><Typography variant="body2" color="text.secondary">{release.status} · {release.commit_sha}</Typography>{release.readiness && <Typography variant="caption" color={release.readiness.passed ? 'success.main' : 'error.main'}>Readiness {release.readiness.passed ? 'passed' : 'blocked'}</Typography>}</Box><Stack direction="row" spacing={1}><Button size="small" variant="outlined" onClick={() => action.mutate({ id: release.id, kind: 'readiness' })} disabled={action.isPending}>Evaluate readiness</Button><Button size="small" color="success" onClick={() => action.mutate({ id: release.id, kind: 'approve' })} disabled={release.status !== 'submitted'}>Approve</Button><Button size="small" variant="contained" onClick={() => action.mutate({ id: release.id, kind: 'package' })} disabled={release.status !== 'approved'}>Package</Button></Stack></Stack></CardContent></Card>)}{!releaseQuery.isLoading && !(releaseQuery.data ?? []).length && <Paper sx={{ p: 3 }}><Typography color="text.secondary">No releases are available. Releases require an approved change set.</Typography></Paper>}</Stack><Typography variant="h6" sx={{ mb: 1 }}>Deployment plans</Typography><Stack spacing={1} sx={{ mb: 4 }}>{(planQuery.data ?? []).map((plan) => <Card key={plan.id}><CardContent><Typography>{plan.environment} · {plan.status}</Typography><Typography variant="caption" color="text.secondary">{plan.content_hash}</Typography></CardContent></Card>)}</Stack><Typography variant="h6" sx={{ mb: 1 }}>Deployments</Typography><Stack spacing={1}>{(deploymentQuery.data ?? []).map((deployment) => <Card key={deployment.id}><CardContent><Stack direction="row" spacing={2}><Chip label={deployment.status}/><Typography>{deployment.environment} · {deployment.provider}</Typography></Stack></CardContent></Card>)}</Stack></> }
