function RepositoryWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ['repository', projectId], queryFn: () => repository(projectId) }); const [dialog, setDialog] = useState(false); const mutation = useMutation({ mutationFn: (data: { ssh_url: string; scope: string; default_branch: string }) => connectRepository(projectId, data), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['repository', projectId] }); setDialog(false) } }); const action = useMutation({ mutationFn: (kind: 'test' | 'rotate-key' | 'revoke' | 'sync') => repositoryAction(projectId, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['repository', projectId] }) }); const { register, handleSubmit, formState: { errors } } = useForm<{ ssh_url: string; scope: string; default_branch: string }>({ defaultValues: { scope: 'rw', default_branch: 'main' } }); return <><PageHeader title="Repository" description="Manage the project SSH connection, host verification, deploy key, and synchronization." action={<Button variant="contained" onClick={() => setDialog(true)} disabled={Boolean(query.data)}>Connect repository</Button>}/>{query.data ? <Card><CardContent><Stack spacing={2}><Stack direction="row" spacing={1}><Chip label={query.data.status}/><Chip label={query.data.host_fingerprint_verified ? 'Host verified' : 'Host unverified'} color={query.data.host_fingerprint_verified ? 'success' : 'warning'}/></Stack><Typography>{query.data.ssh_url}</Typography><Typography variant="body2" color="text.secondary">Branch {query.data.default_branch} · scope {query.data.scope}</Typography><Typography variant="caption" color="text.secondary">Deploy key material is never displayed after creation.</Typography><Stack direction="row" spacing={1} flexWrap="wrap"><Button variant="outlined" onClick={() => action.mutate('test')}>Test connection</Button><Button variant="outlined" onClick={() => action.mutate('sync')}>Sync repository</Button><Button variant="outlined" onClick={() => action.mutate('rotate-key')}>Rotate key</Button><Button color="error" onClick={() => action.mutate('revoke')}>Revoke key</Button></Stack></Stack></CardContent></Card> : <Paper sx={{ p: 4 }}><Typography color="text.secondary">No repository connection configured.</Typography></Paper>}<Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="sm"><DialogTitle>Connect repository</DialogTitle><Box component="form" onSubmit={handleSubmit((data) => mutation.mutate(data))}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}><TextField label="SSH URL" placeholder="git@github.com:org/repository.git" fullWidth error={Boolean(errors.ssh_url)} {...register('ssh_url', { required: true })}/><TextField select label="Scope" fullWidth {...register('scope')}><MenuItem value="ro">Read only</MenuItem><MenuItem value="rw">Read/write</MenuItem></TextField><TextField label="Default branch" fullWidth {...register('default_branch', { required: true })}/></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained">Connect</Button></DialogActions></Box></Dialog></> }
function SecretsPage() { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ['secrets'], queryFn: secrets }); const [dialog, setDialog] = useState(false); const mutation = useMutation({ mutationFn: createSecret, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['secrets'] }); setDialog(false) } }); const action = useMutation({ mutationFn: ({ id, kind }: { id: string; kind: 'rotate' | 'revoke' | 'verify' }) => secretAction(id, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['secrets'] }) }); const { register, handleSubmit } = useForm<{ name: string; value: string; purpose: string }>(); return <><PageHeader title="Secrets" description="Manage secret metadata and lifecycle without exposing secret values." action={<Button variant="contained" onClick={() => setDialog(true)}>Create secret</Button>}/><Alert severity="warning" sx={{ mb: 2 }}>Secret values are write-only and are never rendered, cached, placed in URLs, or copied to logs.</Alert><Stack spacing={1}>{(query.data ?? []).map((secret) => <Card key={secret.id}><CardContent><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}><Box sx={{ flex: 1 }}><Typography fontWeight={600}>{secret.name}</Typography><Typography variant="caption" color="text.secondary">{secret.purpose || 'No purpose'} · {secret.status} · rotated {secret.last_rotated_at || 'never'}</Typography></Box><Button size="small" onClick={() => action.mutate({ id: secret.id, kind: 'verify' })}>Verify</Button><Button size="small" onClick={() => action.mutate({ id: secret.id, kind: 'rotate' })}>Rotate</Button><Button size="small" color="error" onClick={() => action.mutate({ id: secret.id, kind: 'revoke' })}>Revoke</Button></Stack></CardContent></Card>)}</Stack><Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="sm"><DialogTitle>Create secret</DialogTitle><Box component="form" onSubmit={handleSubmit((data) => mutation.mutate(data))}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}><TextField label="Name" fullWidth {...register('name', { required: true })}/><TextField label="Purpose" fullWidth {...register('purpose')}/><TextField label="Secret value" type="password" fullWidth autoComplete="new-password" {...register('value', { required: true })}/></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained">Write secret</Button></DialogActions></Box></Dialog></> }
function SandboxPage() { const readiness = useQuery({ queryKey: ['sandbox-readiness'], queryFn: sandboxReadiness }); const [output, setOutput] = useState<Record<string, unknown> | null>(null); const run = useMutation({ mutationFn: sandboxDiagnostic, onSuccess: setOutput }); const probe = useMutation({ mutationFn: sandboxProbe, onSuccess: setOutput }); return <><PageHeader title="Sandbox" description="Inspect sandbox policy and run constrained diagnostics through the backend boundary."/><Stack direction={{ xs: 'column', md: 'row' }} spacing={2}><Card sx={{ flex: 1 }}><CardContent><Typography variant="h6">Readiness</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{readiness.isLoading ? 'Checking…' : JSON.stringify(readiness.data)}</Typography><Button sx={{ mt: 2 }} variant="outlined" onClick={() => readiness.refetch()}>Refresh readiness</Button></CardContent></Card><Card sx={{ flex: 1 }}><CardContent><Typography variant="h6">Diagnostics</Typography><Typography color="text.secondary">Commands execute only through backend sandbox policy.</Typography><Stack direction="row" spacing={1} sx={{ mt: 2 }}><Button variant="outlined" onClick={() => run.mutate({ image: 'python:3.13-slim' })}>Run diagnostic</Button><Button variant="outlined" onClick={() => probe.mutate({ image: 'python:3.13-slim', command: 'python --version' })}>Run probe</Button></Stack></CardContent></Card></Stack>{output && <Paper sx={{ p: 2, mt: 2, overflow: 'auto' }}><Typography variant="subtitle2">Latest result</Typography><Box component="pre" sx={{ whiteSpace: 'pre-wrap', fontSize: 12 }}>{JSON.stringify(output, null, 2)}</Box></Paper>}</> }
function OperationsPage() { const events = useQuery({ queryKey: ['audit-events'], queryFn: auditEvents }); const verify = useMutation({ mutationFn: auditVerify }); const bundle = useMutation({ mutationFn: diagnosticBundle }); const retention = useQuery({ queryKey: ['retention-plan'], queryFn: retentionPlan }); return <><PageHeader title="Operations" description="Review audit integrity, diagnostic information, retention impact, and operational history."/><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} sx={{ mb: 3 }}><Card sx={{ flex: 1 }}><CardContent><Typography variant="h6">Audit chain</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{verify.data ? JSON.stringify(verify.data) : 'Not checked in this session.'}</Typography><Button sx={{ mt: 2 }} variant="outlined" onClick={() => verify.mutate()}>Verify chain</Button></CardContent></Card><Card sx={{ flex: 1 }}><CardContent><Typography variant="h6">Retention plan</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{retention.data ? JSON.stringify(retention.data) : 'Loading plan…'}</Typography><Button sx={{ mt: 2 }} variant="outlined" onClick={() => bundle.mutate()}>Generate diagnostics bundle</Button></CardContent></Card></Stack><Typography variant="h6" sx={{ mb: 1 }}>Recent audit events ({events.data?.total ?? 0})</Typography><Stack spacing={1}>{(events.data?.events ?? []).slice(0, 20).map((event, index) => <Card key={index}><CardContent sx={{ py: 1.5 }}><Typography variant="body2">{JSON.stringify(event)}</Typography></CardContent></Card>)}</Stack></> }
function AnalysisPanel({ baselineId }: { baselineId: string }) { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ['analyses', baselineId], queryFn: () => analyses(baselineId) }); const [selected, setSelected] = useState(''); const detail = useQuery({ queryKey: ['analysis', selected], queryFn: () => analysis(selected), enabled: Boolean(selected) }); const resolve = useMutation({ mutationFn: ({ analysisId, findingId, status }: { analysisId: string; findingId: string; status: 'resolved' | 'waived' }) => resolveFinding(analysisId, findingId, status, status === 'waived' ? 'Waived by reviewer' : 'Resolved by reviewer'), onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['analysis', selected] }); queryClient.invalidateQueries({ queryKey: ['analyses', baselineId] }) } }); const apply = useMutation({ mutationFn: applyAnalysisWorkItems, onSuccess: () => queryClient.invalidateQueries({ queryKey: ['work-items'] }) }); return <Box sx={{ mt: 2, pl: { md: 2 }, borderLeft: { md: '2px solid #eaecf0' } }}>{(query.data ?? []).length === 0 ? <Typography variant="caption" color="text.secondary">No analysis has been run yet.</Typography> : <><Select size="small" value={selected} displayEmpty onChange={(event) => setSelected(event.target.value)}><MenuItem value=""><em>Inspect analysis findings</em></MenuItem>{(query.data ?? []).map((item) => <MenuItem value={item.id} key={item.id}>v{item.baseline_version} · {item.status}</MenuItem>)}</Select>{detail.data && <Stack spacing={1} sx={{ mt: 2 }}>{detail.data.findings?.map((finding) => <Paper key={finding.id} variant="outlined" sx={{ p: 1.5 }}><Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} alignItems={{ sm: 'center' }}><Chip label={finding.severity} size="small" color={finding.blocking ? 'error' : 'default'}/><Box sx={{ flex: 1 }}><Typography variant="body2" fontWeight={600}>{finding.title}</Typography><Typography variant="caption" color="text.secondary">{finding.description}</Typography></Box>{finding.status === 'open' ? <Stack direction="row"><Button size="small" onClick={() => resolve.mutate({ analysisId: detail.data!.id, findingId: finding.id, status: 'resolved' })}>Resolve</Button><Button size="small" color="warning" onClick={() => resolve.mutate({ analysisId: detail.data!.id, findingId: finding.id, status: 'waived' })}>Waive</Button></Stack> : <Chip label={finding.status} size="small" color="success"/>}</Stack></Paper>)}<Button size="small" variant="outlined" onClick={() => apply.mutate(detail.data!.id)} disabled={apply.isPending}>Apply proposed work items</Button></Stack>}</>}</Box> }

function RequirementsWorkspace({ projectId }: { projectId: string }) {
  const queryClient = useQueryClient();
  const query = useQuery({ queryKey: ['baselines', projectId], queryFn: () => baselines(projectId) });
  const [dialog, setDialog] = useState(false); const [error, setError] = useState('');
  const mutation = useMutation({ mutationFn: createBaseline, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['baselines', projectId] }); setDialog(false) } });
  const action = useMutation({ mutationFn: ({ id, kind }: { id: string; kind: 'submit' | 'analyze' | 'approve' | 'request-changes' }) => baselineAction(id, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['baselines', projectId] }) });
  const { register, handleSubmit, reset, formState: { errors } } = useForm<{ title: string; content: string }>({ defaultValues: { content: '{\n  "goals": ["Describe the outcome this project must deliver"],\n  "functional_specifications": [],\n  "constraints": [],\n  "acceptance_expectations": [],\n  "attachments": [],\n  "repository_references": []\n}' } });
  const submit = async (data: { title: string; content: string }) => { setError(''); try { await mutation.mutateAsync({ title: data.title, content: JSON.parse(data.content), project_id: projectId }); reset() } catch (e) { setError(e instanceof SyntaxError ? 'Requirements content must be valid JSON.' : e instanceof Error ? e.message : 'Unable to create baseline') } };
  return <><PageHeader title="Requirements" description="Create baselines, run analysis, and move approved requirements into traceable work." action={<Button variant="contained" startIcon={<Add/>} onClick={() => setDialog(true)}>New baseline</Button>}/>{query.isLoading ? <CircularProgress/> : <Stack spacing={2}>{(query.data ?? []).map((baseline) => <Card key={baseline.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Stack direction="row" spacing={1} alignItems="center"><Typography variant="h6">{baseline.title}</Typography><Chip label={baseline.status} size="small" color={baseline.status === 'approved' ? 'success' : 'default'}/></Stack><Typography variant="body2" color="text.secondary" sx={{ mt: .5 }}>Version {baseline.current_version} · {baseline.version_count} version(s) · hash {baseline.content_hash ?? 'available on detail'}</Typography></Box><Stack direction="row" spacing={1} flexWrap="wrap"><Button size="small" variant="outlined" disabled={action.isPending || baseline.status !== 'draft'} onClick={() => action.mutate({ id: baseline.id, kind: 'submit' })}>Submit</Button><Button size="small" variant="outlined" disabled={action.isPending || !['draft', 'submitted'].includes(baseline.status)} onClick={() => action.mutate({ id: baseline.id, kind: 'analyze' })}>Analyze</Button><Button size="small" color="success" disabled={action.isPending || baseline.status !== 'submitted'} onClick={() => action.mutate({ id: baseline.id, kind: 'approve' })}>Approve</Button><Button size="small" color="warning" disabled={action.isPending || baseline.status !== 'submitted'} onClick={() => action.mutate({ id: baseline.id, kind: 'request-changes' })}>Request changes</Button></Stack></Stack><AnalysisPanel baselineId={baseline.id}/></CardContent></Card>)}{(query.data ?? []).length === 0 && <Paper sx={{ p: 4 }}><Typography variant="h6">No requirement baselines</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Capture product intent as an immutable, hash-bound baseline.</Typography></Paper>}</Stack>}<Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="md"><DialogTitle>New requirement baseline</DialogTitle><Box component="form" onSubmit={handleSubmit(submit)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Title" fullWidth error={Boolean(errors.title)} {...register('title', { required: true })}/><TextField label="Requirements content (JSON)" fullWidth multiline minRows={12} error={Boolean(errors.content)} helperText="Structured content is hashed and versioned by the backend." {...register('content', { required: true })}/></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained" disabled={mutation.isPending}>Create baseline</Button></DialogActions></Box></Dialog></>
}

function WorkItemsPage() { return <ProjectRequired>{(projectId) => <WorkItemsWorkspace projectId={projectId}/>}</ProjectRequired> }
function WorkItemTree({ projectId }: { projectId: string }) { const query = useQuery({ queryKey: ['work-item-tree', projectId], queryFn: () => workItemTree(projectId) }); const render = (nodes: unknown[], depth = 0): ReactNode[] => nodes.map((raw, index) => { const node = raw as { code?: string; title?: string; kind?: string; children?: unknown[] }; return <Box key={node.code ?? index} sx={{ ml: depth * 3, py: .5 }}><Typography variant="body2"><strong>{node.code ?? 'Item'}</strong> · {node.title ?? 'Untitled'} <Typography component="span" variant="caption" color="text.secondary">({node.kind ?? 'work item'})</Typography></Typography>{node.children && render(node.children, depth + 1)}</Box> }); return <Card variant="outlined" sx={{ mb: 2 }}><CardContent><Typography variant="subtitle1">Hierarchy</Typography>{query.isLoading ? <CircularProgress size={18}/> : query.data && query.data.length ? render(query.data) : <Typography variant="caption" color="text.secondary">No hierarchy yet.</Typography>}</CardContent></Card> }
function WorkItemsWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ['work-items', projectId], queryFn: () => workItems(projectId) }); const baselineQuery = useQuery({ queryKey: ['baselines', projectId], queryFn: () => baselines(projectId) }); const [dialog, setDialog] = useState(false); const [error, setError] = useState(''); const mutation = useMutation({ mutationFn: createWorkItem, onSuccess: () => { queryClient.invalidateQueries({ queryKey: ['work-items', projectId] }); queryClient.invalidateQueries({ queryKey: ['work-item-tree', projectId] }); setDialog(false) } }); const { register, handleSubmit, reset, formState: { errors } } = useForm<{ kind: string; title: string; description: string; priority: string; risk: string; source_baseline_id: string }>({ defaultValues: { kind: 'story', priority: 'medium', risk: 'low' } }); const submit = async (data: { kind: string; title: string; description: string; priority: string; risk: string; source_baseline_id: string }) => { setError(''); try { await mutation.mutateAsync({ ...data, project_id: projectId, source_baseline_id: data.source_baseline_id || undefined }); reset(); } catch (e) { setError(e instanceof Error ? e.message : 'Unable to create work item') } }; return <><PageHeader title="Work items" description="Turn approved product intent into an ordered, risk-aware delivery hierarchy." action={<Button variant="contained" startIcon={<Add/>} onClick={() => setDialog(true)}>New work item</Button>}/><WorkItemTree projectId={projectId}/>{query.isLoading ? <CircularProgress/> : <Stack spacing={1}>{(query.data ?? []).map((item) => <Card key={item.id}><CardContent sx={{ py: 2 }}><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}><Chip label={item.code} size="small" color="primary" variant="outlined"/><Box sx={{ flex: 1 }}><Typography fontWeight={600}>{item.title}</Typography><Typography variant="caption" color="text.secondary">{item.kind} · {item.priority} priority · {item.risk} risk</Typography></Box><Chip label={item.status} size="small"/></Stack></CardContent></Card>)}{(query.data ?? []).length === 0 && <Paper sx={{ p: 4 }}><Typography variant="h6">No work items</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Create traceable epics, features, stories, tasks, and tests.</Typography></Paper>}</Stack>}<Dialog open={dialog} onClose={() => setDialog(false)} fullWidth maxWidth="sm"><DialogTitle>New work item</DialogTitle><Box component="form" onSubmit={handleSubmit(submit)}><DialogContent><Stack spacing={2} sx={{ pt: 1 }}>{error && <Alert severity="error">{error}</Alert>}<TextField select label="Kind" fullWidth {...register('kind')}><MenuItem value="epic">Epic</MenuItem><MenuItem value="feature">Feature</MenuItem><MenuItem value="story">Story</MenuItem><MenuItem value="task">Task</MenuItem><MenuItem value="test">Test</MenuItem></TextField><TextField label="Title" fullWidth error={Boolean(errors.title)} {...register('title', { required: true })}/><TextField label="Description" fullWidth multiline minRows={2} {...register('description')}/><Stack direction="row" spacing={2}><TextField select label="Priority" fullWidth {...register('priority')}><MenuItem value="low">Low</MenuItem><MenuItem value="medium">Medium</MenuItem><MenuItem value="high">High</MenuItem><MenuItem value="critical">Critical</MenuItem></TextField><TextField select label="Risk" fullWidth {...register('risk')}><MenuItem value="low">Low</MenuItem><MenuItem value="medium">Medium</MenuItem><MenuItem value="high">High</MenuItem></TextField></Stack><TextField select label="Source baseline (optional)" fullWidth {...register('source_baseline_id')}><MenuItem value="">None</MenuItem>{(baselineQuery.data ?? []).map((baseline) => <MenuItem value={baseline.id} key={baseline.id}>{baseline.title}</MenuItem>)}</TextField></Stack></DialogContent><DialogActions><Button onClick={() => setDialog(false)}>Cancel</Button><Button type="submit" variant="contained" disabled={mutation.isPending}>Create work item</Button></DialogActions></Box></Dialog></> }

function GatesPage() { return <ProjectRequired>{(projectId) => <GatesWorkspace projectId={projectId}/>}</ProjectRequired> }
function GateReviewPanel({ projectId, gate }: { projectId: string; gate: { number: number; status: string; missing_decisions: string[] } }) { const queryClient = useQueryClient(); const [responsibility, setResponsibility] = useState('organization_administrator'); const [decision, setDecision] = useState('approved'); const decide = useMutation({ mutationFn: () => gateDecision(projectId, gate.number, { responsibility_type: responsibility, decision }), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['gates', projectId] }) }); const close = useMutation({ mutationFn: () => closeGate(projectId, gate.number), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['gates', projectId] }) }); const history = useQuery({ queryKey: ['gate-history', projectId, gate.number], queryFn: () => gateHistory(projectId, gate.number) }); return <Stack direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ mt: 2 }}><Select size="small" value={responsibility} onChange={(event) => setResponsibility(event.target.value)}><MenuItem value="organization_administrator">Organization administrator</MenuItem><MenuItem value="product_owner">Product owner</MenuItem><MenuItem value="architecture_reviewer">Architecture reviewer</MenuItem><MenuItem value="qa_reviewer">QA reviewer</MenuItem><MenuItem value="release_manager">Release manager</MenuItem></Select><Select size="small" value={decision} onChange={(event) => setDecision(event.target.value)}><MenuItem value="approved">Approve</MenuItem><MenuItem value="rejected">Reject</MenuItem><MenuItem value="changes_requested">Request changes</MenuItem></Select><Button size="small" variant="outlined" onClick={() => decide.mutate()} disabled={decide.isPending}>Record decision</Button><Button size="small" variant="contained" onClick={() => close.mutate()} disabled={close.isPending || gate.status !== 'ready'}>Close gate</Button><Chip size="small" label={`${history.data?.length ?? 0} history events`} variant="outlined"/></Stack> }
function GatesWorkspace({ projectId }: { projectId: string }) { const queryClient = useQueryClient(); const query = useQuery({ queryKey: ['gates', projectId], queryFn: () => gates(projectId) }); const action = useMutation({ mutationFn: ({ number, kind }: { number: number; kind: 'sync' | 'evaluate' }) => gateAction(projectId, number, kind), onSuccess: () => queryClient.invalidateQueries({ queryKey: ['gates', projectId] }) }); return <><PageHeader title="Approvals & gates" description="Inspect evidence, evaluate lifecycle gates, and keep approval decisions auditable." action={<Button variant="outlined" onClick={() => query.refetch()}>Refresh</Button>}/>{query.isLoading ? <CircularProgress/> : <Stack spacing={2}>{(query.data ?? []).map((gate) => <Card key={gate.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}><Box sx={{ flex: 1 }}><Stack direction="row" spacing={1} alignItems="center"><Chip label={`Gate ${gate.number}`} color="primary"/><Typography variant="h6">{gate.name}</Typography><Chip label={gate.status} size="small" color={gate.status === 'closed' ? 'success' : gate.status === 'ready' ? 'warning' : 'default'}/></Stack><Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>{gate.blocking_checks.length} blocking evidence check(s) · {gate.missing_decisions.length} missing decision(s)</Typography></Box><Stack direction="row" spacing={1}><Button size="small" variant="outlined" disabled={action.isPending} onClick={() => action.mutate({ number: gate.number, kind: 'sync' })}>Sync evidence</Button><Button size="small" variant="contained" disabled={action.isPending} onClick={() => action.mutate({ number: gate.number, kind: 'evaluate' })}>Evaluate</Button></Stack></Stack><GateReviewPanel projectId={projectId} gate={gate}/></CardContent></Card>)}</Stack>}</> }
function ApprovalsPage() { const query = useQuery({ queryKey: ['approvals'], queryFn: () => approvals() }); return <><PageHeader title="Approvals" description="Review immutable approval decisions and their bound artifact versions."/><Stack spacing={1}>{(query.data ?? []).map((item, index) => <Card key={index}><CardContent><Typography variant="body2">{JSON.stringify(item)}</Typography></CardContent></Card>)}{!query.isLoading && (query.data ?? []).length === 0 && <Paper sx={{ p: 4 }}><Typography variant="h6">No approval decisions</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Approval history will appear here as reviewers make decisions.</Typography></Paper>}</Stack></> }

function OrganizationPage() { const client = useQueryClient(); const org = useQuery({ queryKey: ['organization'], queryFn: organization }); const users = useQuery({ queryKey: ['organization-users'], queryFn: organizationUsers }); const roles = useQuery({ queryKey: ['organization-roles'], queryFn: organizationRoles }); const policy = useQuery({ queryKey: ['gate-policy'], queryFn: gatePolicy }); const [message, setMessage] = useState(''); const create = useMutation({ mutationFn: createOrganizationUser, onSuccess: () => { client.invalidateQueries({ queryKey: ['organization-users'] }); setMessage('User created.') } }); const saveSettings = useMutation({ mutationFn: updateOrganizationSettings, onSuccess: () => { client.invalidateQueries({ queryKey: ['organization'] }); setMessage('Organization settings updated.') } }); const savePolicy = useMutation({ mutationFn: updateGatePolicy, onSuccess: () => { client.invalidateQueries({ queryKey: ['gate-policy'] }); setMessage('Gate policy updated.') } }); const form = useForm<{ email: string; display_name: string; password: string; roles: string }>({ defaultValues: { roles: 'developer' } }); const policyForm = useForm<{ require_gate_decisions: boolean; allow_waivers: boolean; require_previous_gate_closed: boolean }>({ defaultValues: { require_gate_decisions: true, allow_waivers: true, require_previous_gate_closed: true } }); return <><PageHeader title="Organization administration" description="Manage members, roles, policy, and organization-scoped delivery controls."/>{message && <Alert sx={{ mb: 2 }} severity="success">{message}</Alert>}<Stack spacing={3} sx={{ maxWidth: 1100 }}><Card><CardContent><Typography variant="h6">Organization profile</Typography><Typography color="text.secondary">{org.data?.name} · {org.data?.slug}</Typography><Button sx={{ mt: 2 }} variant="outlined" onClick={() => saveSettings.mutate({ enforce_project_responsibilities: !(org.data?.settings.enforce_project_responsibilities === true) })}>{org.data?.settings.enforce_project_responsibilities === true ? 'Disable' : 'Enable'} responsibility enforcement</Button></CardContent></Card><Card><CardContent><Typography variant="h6">Members</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(users.data ?? []).map((user) => <Stack key={user.id} direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}><Box sx={{ flex: 1 }}><Typography>{user.display_name} · {user.email}</Typography><Typography variant="caption" color="text.secondary">{user.roles.join(', ')} · {user.is_active ? 'active' : 'inactive'}</Typography></Box><Button size="small" onClick={() => replaceOrganizationUserRoles(user.id, user.roles).then(() => setMessage('Roles saved.'))}>Save roles</Button></Stack>)}</Stack><Divider sx={{ my: 2 }}/><Typography variant="subtitle1">Create member</Typography><Stack component="form" onSubmit={form.handleSubmit((data) => create.mutate({ ...data, roles: data.roles.split(',').map((role) => role.trim()).filter(Boolean) }))} direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ mt: 1 }}><TextField label="Display name" {...form.register('display_name', { required: true })}/><TextField label="Email" type="email" {...form.register('email', { required: true })}/><TextField label="Temporary password" type="password" {...form.register('password', { required: true, minLength: 12 })}/><TextField label="Roles" helperText="Comma-separated" {...form.register('roles')}/><Button type="submit" variant="contained">Create</Button></Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Roles and scopes</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(roles.data ?? []).map((role) => <Stack key={role.name} direction={{ xs: 'column', sm: 'row' }} spacing={2}><Typography sx={{ minWidth: 250 }}>{role.name}</Typography><Typography variant="body2" color="text.secondary">{role.scopes.join(', ')}</Typography></Stack>)}</Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Gate policy</Typography><Typography variant="caption" color="text.secondary">Version {policy.data?.version ?? 'loading'}</Typography><Stack component="form" onSubmit={policyForm.handleSubmit((data) => savePolicy.mutate(data))} spacing={1} sx={{ mt: 2 }}>{[['require_gate_decisions', 'Require gate decisions'], ['allow_waivers', 'Allow waivers'], ['require_previous_gate_closed', 'Require previous gate closure']].map(([name, label]) => <label key={name}><input type="checkbox" {...policyForm.register(name as 'require_gate_decisions' | 'allow_waivers' | 'require_previous_gate_closed')} /> {label}</label>)}<Button type="submit" variant="outlined">Save gate policy</Button></Stack></CardContent></Card></Stack></> }

function ProjectDetailPage() { const { projectId = '' } = useParams<{ projectId: string }>(); const details = useQuery({ queryKey: ['project', projectId], queryFn: () => project(projectId), enabled: Boolean(projectId) }); const assignments = useQuery({ queryKey: ['responsibilities', projectId], queryFn: () => responsibilities(projectId), enabled: Boolean(projectId) }); const users = useQuery({ queryKey: ['organization-users'], queryFn: organizationUsers }); const client = useQueryClient(); const mutation = useMutation({ mutationFn: (payload: Record<string, unknown>) => createResponsibility(projectId, payload), onSuccess: () => client.invalidateQueries({ queryKey: ['responsibilities', projectId] }) }); const form = useForm<{ user_id: string; responsibility_type: string; effective_from: string; effective_until: string; is_primary: boolean }>({ defaultValues: { responsibility_type: 'developer', is_primary: true } }); const repositoryStatus = (details.data?.repository as { status?: string } | null | undefined)?.status; return <><PageHeader title={details.data?.name ?? 'Project detail'} description="Project lifecycle, repository context, responsibilities, and governance assignments."/><Stack spacing={3} sx={{ maxWidth: 1100 }}><Card><CardContent><Stack direction={{ xs: 'column', sm: 'row' }} spacing={3}><Box sx={{ flex: 1 }}><Typography variant="h6">{details.data?.key}</Typography><Typography color="text.secondary">{details.data?.description || 'No description'}</Typography></Box><Chip label={details.data?.lifecycle_state ?? 'loading'} color="primary"/><Chip label={details.data?.archived ? 'Archived' : 'Active'} variant="outlined"/></Stack><Typography variant="body2" sx={{ mt: 2 }}>Default branch: {details.data?.default_branch} · Repository: {repositoryStatus ?? 'not connected'}</Typography></CardContent></Card><Card><CardContent><Typography variant="h6">Responsibility assignments</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(assignments.data ?? []).map((item) => <Stack key={item.id} direction={{ xs: 'column', sm: 'row' }} spacing={2}><Chip label={item.responsibility_type} size="small"/><Typography sx={{ flex: 1 }}>{item.user_display_name ?? item.user_id}</Typography><Typography variant="caption" color="text.secondary">{item.is_primary ? 'Primary' : 'Backup'} · {item.effective_from ?? 'effective now'}</Typography></Stack>)}{!assignments.isLoading && !(assignments.data ?? []).length && <Typography color="text.secondary">No responsibilities assigned yet.</Typography>}</Stack><Divider sx={{ my: 2 }}/><Typography variant="subtitle1">Assign responsibility</Typography><Stack component="form" onSubmit={form.handleSubmit((data) => mutation.mutate({ ...data, project_id: projectId }))} direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ mt: 1 }}><TextField select label="User" {...form.register('user_id', { required: true })}>{(users.data ?? []).filter((user) => user.is_active).map((user) => <MenuItem value={user.id} key={user.id}>{user.display_name} · {user.email}</MenuItem>)}</TextField><TextField select label="Responsibility" {...form.register('responsibility_type')}><MenuItem value="product_owner">Product owner</MenuItem><MenuItem value="architecture_reviewer">Architecture reviewer</MenuItem><MenuItem value="developer">Developer</MenuItem><MenuItem value="qa_reviewer">QA reviewer</MenuItem><MenuItem value="designer">Designer</MenuItem><MenuItem value="release_manager">Release manager</MenuItem><MenuItem value="security_approver">Security approver</MenuItem><MenuItem value="operations_approver">Operations approver</MenuItem></TextField><Button type="submit" variant="contained">Assign</Button></Stack></CardContent></Card></Stack></> }

function ArchitectureDetailPage() { const { architectureId = '' } = useParams<{ architectureId: string }>(); const query = useQuery({ queryKey: ['architecture-detail', architectureId], queryFn: () => architecturePackage(architectureId), enabled: Boolean(architectureId) }); const comments = useQuery({ queryKey: ['architecture-comments', architectureId], queryFn: () => architectureComments(architectureId), enabled: Boolean(architectureId) }); const client = useQueryClient(); const adrMutation = useMutation({ mutationFn: (payload: { key: string; title: string; context: string; decision: string; consequences: string }) => createAdr(architectureId, payload), onSuccess: () => client.invalidateQueries({ queryKey: ['architecture-detail', architectureId] }) }); const commentMutation = useMutation({ mutationFn: (body: string) => addArchitectureComment(architectureId, { body }), onSuccess: () => client.invalidateQueries({ queryKey: ['architecture-comments', architectureId] }) }); const adrForm = useForm<{ key: string; title: string; context: string; decision: string; consequences: string }>(); const commentForm = useForm<{ body: string }>(); const artifact = query.data as (typeof query.data & { adrs?: { id: string; key: string; title: string; decision: string; consequences: string; status: string }[]; comments?: unknown[] }) | undefined; return <><PageHeader title={artifact?.title ?? 'Architecture detail'} description="Version-bound architecture content, ADRs, comments, and immutable review context."/><Stack spacing={3}><Card><CardContent><Stack direction="row" spacing={1}><Chip label={artifact?.status ?? 'loading'}/><Typography variant="body2">Version {artifact?.current_version ?? '-'} · hash {artifact?.content_hash ?? '-'}</Typography></Stack><Paper variant="outlined" sx={{ p: 2, mt: 2, overflow: 'auto', maxHeight: 420 }}><pre style={{ margin: 0 }}>{JSON.stringify(artifact?.content ?? {}, null, 2)}</pre></Paper></CardContent></Card><Card><CardContent><Typography variant="h6">Architecture decision records</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(artifact?.adrs ?? []).map((adr) => <Paper variant="outlined" sx={{ p: 2 }} key={adr.id}><Stack direction="row" spacing={1}><Chip label={adr.key} size="small"/><Typography fontWeight={600}>{adr.title}</Typography><Chip label={adr.status} size="small" variant="outlined"/></Stack><Typography variant="body2" sx={{ mt: 1 }}>{adr.decision}</Typography><Typography variant="caption" color="text.secondary">Consequences: {adr.consequences}</Typography></Paper>)}</Stack><Divider sx={{ my: 2 }}/><Typography variant="subtitle1">Add ADR</Typography><Stack component="form" onSubmit={adrForm.handleSubmit((data) => adrMutation.mutate(data))} spacing={1} sx={{ mt: 1 }}><Stack direction={{ xs: 'column', md: 'row' }} spacing={1}><TextField label="Key" {...adrForm.register('key', { required: true })}/><TextField label="Title" fullWidth {...adrForm.register('title', { required: true })}/></Stack><TextField label="Context" multiline minRows={2} {...adrForm.register('context', { required: true })}/><TextField label="Decision" multiline minRows={2} {...adrForm.register('decision', { required: true })}/><TextField label="Consequences" multiline minRows={2} {...adrForm.register('consequences', { required: true })}/><Button type="submit" variant="contained" disabled={artifact?.status !== 'draft' && artifact?.status !== 'changes_requested'}>Add ADR</Button></Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Review comments</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(comments.data ?? []).map((comment) => <Stack direction="row" spacing={1} key={comment.id}><Chip label={comment.status} size="small"/><Typography sx={{ flex: 1 }}>{comment.body}</Typography>{comment.status === 'open' && <Button size="small" onClick={() => resolveArchitectureComment(comment.id).then(() => client.invalidateQueries({ queryKey: ['architecture-comments', architectureId] }))}>Resolve</Button>}</Stack>)}</Stack><Stack component="form" onSubmit={commentForm.handleSubmit((data) => commentMutation.mutate(data.body))} direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 2 }}><TextField label="Add review comment" fullWidth {...commentForm.register('body', { required: true })}/><Button type="submit" variant="outlined">Comment</Button></Stack></CardContent></Card></Stack></> }

function TraceabilityPage() { return <ProjectRequired>{(projectId) => <TraceabilityWorkspace projectId={projectId}/>}</ProjectRequired> }
function TraceabilityWorkspace({ projectId }: { projectId: string }) { const query = useQuery({ queryKey: ['trace-links'], queryFn: traceLinks }); const client = useQueryClient(); const mutation = useMutation({ mutationFn: createTraceLink, onSuccess: () => client.invalidateQueries({ queryKey: ['trace-links'] }) }); const form = useForm<{ source_type: string; source_id: string; target_type: string; target_id: string; relation: string }>({ defaultValues: { source_type: 'requirement_baseline', target_type: 'work_item', relation: 'satisfies' } }); const visible = (query.data ?? []).filter((link) => link.project_id === projectId); return <><PageHeader title="Traceability" description="Searchable, project-scoped relationships between requirements, work, architecture, plans, and design."/><Card sx={{ mb: 3 }}><CardContent><Typography variant="h6">Create trace link</Typography><Stack component="form" onSubmit={form.handleSubmit((data) => mutation.mutate(data))} direction={{ xs: 'column', md: 'row' }} spacing={1} sx={{ mt: 2 }}><TextField select label="Source type" {...form.register('source_type')}><MenuItem value="requirement_baseline">Requirement baseline</MenuItem><MenuItem value="work_item">Work item</MenuItem><MenuItem value="architecture">Architecture</MenuItem><MenuItem value="technical_plan">Technical plan</MenuItem><MenuItem value="mockup">Mockup</MenuItem></TextField><TextField label="Source ID" {...form.register('source_id', { required: true })}/><TextField select label="Target type" {...form.register('target_type')}><MenuItem value="work_item">Work item</MenuItem><MenuItem value="architecture">Architecture</MenuItem><MenuItem value="technical_plan">Technical plan</MenuItem><MenuItem value="mockup">Mockup</MenuItem></TextField><TextField label="Target ID" {...form.register('target_id', { required: true })}/><TextField label="Relation" {...form.register('relation', { required: true })}/><Button type="submit" variant="contained">Link</Button></Stack></CardContent></Card><Stack spacing={1}>{visible.map((link) => <Card key={link.id}><CardContent><Stack direction={{ xs: 'column', md: 'row' }} spacing={1} alignItems={{ md: 'center' }}><Chip label={link.source_type} size="small"/><Typography>{link.source_id}</Typography><Typography color="text.secondary">— {link.relation} →</Typography><Chip label={link.target_type} size="small"/><Typography sx={{ flex: 1 }}>{link.target_id}</Typography><Button size="small" color="error" onClick={() => deleteTraceLink(link.id).then(() => client.invalidateQueries({ queryKey: ['trace-links'] }))}>Remove</Button></Stack></CardContent></Card>)}{!visible.length && <Paper sx={{ p: 3 }}><Typography color="text.secondary">No links exist for this project yet.</Typography></Paper>}</Stack></> }

function OperationsControlPage() { const live = useQuery({ queryKey: ['health-live'], queryFn: healthLive }); const generatedLive = useQuery({ queryKey: ['generated-health-live'], queryFn: healthLiveness }); const ready = useQuery({ queryKey: ['health-ready'], queryFn: healthReady }); const metrics = useQuery({ queryKey: ['health-metrics'], queryFn: healthMetrics }); const retention = useQuery({ queryKey: ['retention-plan'], queryFn: retentionPlan }); const generatedStatus = (generatedLive.data as { data?: { status?: string } } | undefined)?.data?.status; const exportAudit = useMutation({ mutationFn: auditExport }); const execute = useMutation({ mutationFn: executeRetention }); return <><PageHeader title="Operations control" description="Health, metrics, audit export, diagnostic retention, and controlled retention execution."/><Stack spacing={2}><Card><CardContent><Typography variant="h6">Service health</Typography><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} sx={{ mt: 2 }}><Chip label={`Live: ${live.data?.status ?? 'loading'}`} color={live.data?.status === 'ok' ? 'success' : 'default'}/><Chip label={`Generated contract: ${generatedStatus ?? 'loading'}`} color={generatedStatus === 'ok' ? 'success' : 'default'}/><Chip label={`Ready: ${ready.data?.status ?? 'loading'}`} color={ready.data?.status === 'ready' ? 'success' : 'warning'}/></Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Metrics snapshot</Typography><Paper variant="outlined" sx={{ p: 2, mt: 1, maxHeight: 240, overflow: 'auto' }}><pre style={{ margin: 0 }}>{JSON.stringify(metrics.data ?? {}, null, 2)}</pre></Paper></CardContent></Card><Card><CardContent><Typography variant="h6">Audit export and retention</Typography><Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} sx={{ mt: 2 }}><Button variant="outlined" onClick={() => exportAudit.mutate()}>Export audit events</Button><Button variant="outlined" onClick={() => execute.mutate({ dry_run: true })}>Preview retention execution</Button><Button color="error" variant="contained" onClick={() => { if (window.confirm('Execute irreversible retention deletion?')) execute.mutate({ dry_run: false, confirm: true }) }}>Execute retention</Button></Stack><Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 2 }}>Current plan: {JSON.stringify(retention.data ?? {})}</Typography>{exportAudit.data && <Typography variant="caption">Exported {exportAudit.data.count} event(s).</Typography>}</CardContent></Card></Stack></> }

function RequirementDetailPage() { const { baselineId = '' } = useParams<{ baselineId: string }>(); const item = useQuery({ queryKey: ['baseline', baselineId], queryFn: () => baseline(baselineId), enabled: Boolean(baselineId) }); const versions = useQuery({ queryKey: ['baseline-versions', baselineId], queryFn: () => baselineVersions(baselineId), enabled: Boolean(baselineId) }); const analysesQuery = useQuery({ queryKey: ['baseline-analyses', baselineId], queryFn: () => analyses(baselineId), enabled: Boolean(baselineId) }); return <><PageHeader title={item.data?.title ?? 'Requirement baseline'} description="Immutable baseline metadata, version history, content hash, and analysis evidence."/><Stack spacing={2}><Card><CardContent><Stack direction="row" spacing={1}><Chip label={item.data?.status ?? 'loading'}/><Typography>Current version {item.data?.current_version ?? '-'} · hash {item.data?.content_hash ?? 'not available'}</Typography></Stack><Paper variant="outlined" sx={{ mt: 2, p: 2, maxHeight: 360, overflow: 'auto' }}><pre style={{ margin: 0 }}>{JSON.stringify(item.data?.content ?? {}, null, 2)}</pre></Paper></CardContent></Card><Card><CardContent><Typography variant="h6">Version history</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(versions.data ?? []).map((version, index) => <Paper variant="outlined" sx={{ p: 1.5 }} key={index}><Typography variant="body2">{JSON.stringify(version)}</Typography></Paper>)}{!versions.isLoading && !(versions.data ?? []).length && <Typography color="text.secondary">No version records returned.</Typography>}</Stack></CardContent></Card><Card><CardContent><Typography variant="h6">Analysis runs</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(analysesQuery.data ?? []).map((run) => <Stack direction="row" spacing={1} key={run.id}><Chip label={run.status} size="small"/><Typography>{run.id}</Typography><Typography color="text.secondary">version {run.baseline_version}</Typography></Stack>)}</Stack></CardContent></Card></Stack></> }

function WorkItemDetailPage() { const { workItemId = '' } = useParams<{ workItemId: string }>(); const item = useQuery({ queryKey: ['work-item', workItemId], queryFn: () => workItem(workItemId), enabled: Boolean(workItemId) }); const dependencies = useQuery({ queryKey: ['work-item-dependencies', workItemId], queryFn: () => workItemDependencies(workItemId), enabled: Boolean(workItemId) }); return <><PageHeader title={item.data?.title ?? 'Work item'} description="Detailed delivery item view with ownership, acceptance context, risk, and dependency traceability."/><Stack spacing={2}><Card><CardContent><Stack direction="row" spacing={1}><Chip label={item.data?.kind ?? 'item'}/><Chip label={item.data?.status ?? 'loading'} color="primary"/><Chip label={`Risk: ${item.data?.risk ?? '-'}`} variant="outlined"/></Stack><Typography variant="h6" sx={{ mt: 2 }}>{item.data?.code}</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{item.data?.description || 'No description provided.'}</Typography><Divider sx={{ my: 2 }}/><Typography variant="body2">Priority: {item.data?.priority ?? '-'} · Estimate: {item.data?.estimate ?? '-'} · Parent: {item.data?.parent_id ?? 'none'}</Typography></CardContent></Card><Card><CardContent><Typography variant="h6">Dependencies</Typography><Stack spacing={1} sx={{ mt: 2 }}>{(dependencies.data ?? []).map((dependency) => <Stack direction="row" spacing={1} key={dependency.id}><Chip label={dependency.kind} size="small"/><Typography>{dependency.code}</Typography><Typography color="text.secondary">{dependency.title}</Typography></Stack>)}{!dependencies.isLoading && !(dependencies.data ?? []).length && <Typography color="text.secondary">No dependencies recorded.</Typography>}</Stack></CardContent></Card></Stack></> }

function PlanDetailPage() { const { planId = '' } = useParams<{ planId: string }>(); const item = useQuery({ queryKey: ['plan', planId], queryFn: () => plan(planId), enabled: Boolean(planId) }); return <><PageHeader title={item.data?.title ?? 'Technical plan'} description="Versioned implementation plan with source architecture, review state, and approval context."/><Card><CardContent><Stack direction="row" spacing={1}><Chip label={item.data?.status ?? 'loading'} color="primary"/><Typography>Version {item.data?.current_version ?? '-'} · hash {item.data?.content_hash ?? '-'}</Typography></Stack><Paper variant="outlined" sx={{ mt: 2, p: 2, maxHeight: 520, overflow: 'auto' }}><pre style={{ margin: 0 }}>{JSON.stringify(item.data?.content ?? {}, null, 2)}</pre></Paper></CardContent></Card></> }

function AgentRunDetailPage() { const { runId = '' } = useParams<{ runId: string }>(); const item = useQuery({ queryKey: ['agent-run', runId], queryFn: () => agentRun(runId), enabled: Boolean(runId) }); return <><PageHeader title={item.data?.objective ?? 'Agent run'} description="Execution lease, budget, tools, writable paths, checkpoints, and operator controls."/><Stack spacing={2}><Card><CardContent><Stack direction="row" spacing={1}><Chip label={item.data?.status ?? 'loading'} color={item.data?.status === 'completed' ? 'success' : 'primary'}/><Typography>Plan version {item.data?.plan_version ?? '-'}</Typography></Stack><Typography sx={{ mt: 2 }}>Current step: {item.data?.current_step ?? 'not started'}</Typography><Typography color="text.secondary">Pause reason: {item.data?.pause_reason ?? 'none'}</Typography></CardContent></Card><Card><CardContent><Typography variant="h6">Execution policy</Typography><Typography sx={{ mt: 1 }}>Allowed tools: {(item.data?.allowed_tools ?? []).join(', ') || 'none'}</Typography><Typography>Writable paths: {(item.data?.writable_paths ?? []).join(', ') || 'none'}</Typography><Typography>Budget: {JSON.stringify(item.data?.budget ?? {})}</Typography></CardContent></Card></Stack></> }

function ReleaseDetailPage() { const { releaseId = '' } = useParams<{ releaseId: string }>(); const item = useQuery({ queryKey: ['release', releaseId], queryFn: () => release(releaseId), enabled: Boolean(releaseId) }); return <><PageHeader title={item.data?.version ? `Release ${item.data.version}` : 'Release detail'} description="Release readiness, immutable package identity, deployment evidence, and rollback context."/><Card><CardContent><Stack direction="row" spacing={1}><Chip label={item.data?.status ?? 'loading'} color="primary"/><Typography>Commit {item.data?.commit_sha ?? '-'}</Typography></Stack><Divider sx={{ my: 2 }}/><Typography variant="h6">Readiness</Typography><Typography sx={{ mt: 1 }}>Passed: {item.data?.readiness?.passed === undefined ? 'not evaluated' : String(item.data.readiness.passed)}</Typography><Typography color="text.secondary">Blocking checks: {(item.data?.readiness?.blocking ?? []).join(', ') || 'none reported'}</Typography><Paper variant="outlined" sx={{ mt: 2, p: 2 }}><pre style={{ margin: 0 }}>{JSON.stringify(item.data?.package ?? {}, null, 2)}</pre></Paper></CardContent></Card></> }

function DeploymentDetailPage() { const { deploymentId = '' } = useParams<{ deploymentId: string }>(); const item = useQuery({ queryKey: ['deployment', deploymentId], queryFn: () => deployment(deploymentId), enabled: Boolean(deploymentId) }); return <><PageHeader title="Deployment detail" description="Provider identity, environment, health checks, diagnostics, and rollback controls."/><Card><CardContent><Stack direction="row" spacing={1}><Chip label={item.data?.status ?? 'loading'} color={item.data?.status === 'succeeded' ? 'success' : 'primary'}/><Chip label={item.data?.environment ?? '-'} variant="outlined"/><Typography>Provider: {item.data?.provider ?? '-'}</Typography></Stack><Typography sx={{ mt: 2 }}>Release: {item.data?.release_id ?? '-'}</Typography><Typography color="text.secondary">Provider deployment ID: {item.data?.provider_deployment_id ?? 'not assigned'}</Typography></CardContent></Card></> }

function FeatureGate({ flag, children }: { flag: FeatureFlag; children: ReactNode }) { return featureFlags[flag] ? <>{children}</> : <Box component="main"><PageHeader title="Feature unavailable" description="This workspace is not enabled for the current rollout."/><Alert severity="info">The feature flag <strong>{flag}</strong> is disabled. Contact an administrator to request enablement.</Alert></Box> }

function Shell() {
  const { session, signOut } = useAuth(); const [open, setOpen] = useState(false); const mobile = useMediaQuery('(max-width:900px)'); const location = useLocation(); const current = [...nav, ...management].find((item) => item.path !== '/' && location.pathname.startsWith(item.path)) ?? nav[0]
  const content = <Box sx={{ width: 270, height: '100%', bgcolor: '#101828', color: '#d0d5dd', display: 'flex', flexDirection: 'column' }}><Toolbar sx={{ px: 2.5 }}><Typography variant="h6" sx={{ color: 'white', fontWeight: 800, flex: 1 }}>botq<span style={{ color: '#84adff' }}>.</span></Typography>{mobile && <IconButton onClick={() => setOpen(false)} sx={{ color: 'white' }}><ChevronLeft/></IconButton>}</Toolbar><Divider sx={{ borderColor: '#344054' }}/><Box sx={{ p: 2 }}><Typography variant="overline" sx={{ color: '#98a2b3' }}>Workspace</Typography><Select size="small" fullWidth defaultValue="cdx" sx={{ mt: 1, color: 'white', '.MuiOutlinedInput-notchedOutline': { borderColor: '#475467' }, '& .MuiSvgIcon-root': { color: 'white' } }}><MenuItem value="cdx">COSQ Network</MenuItem></Select></Box><List sx={{ px: 1, overflow: 'auto', flex: 1 }}>{nav.map((item) => <ListItemButton key={item.path} component={NavLink} to={item.path} onClick={() => setOpen(false)} sx={{ borderRadius: 1, mb: .25, color: 'inherit', '&.active': { bgcolor: '#194185', color: 'white' } }}><ListItemIcon sx={{ color: 'inherit', minWidth: 38 }}>{item.icon}</ListItemIcon><ListItemText primary={item.label}/></ListItemButton>)}<Typography variant="overline" sx={{ display: 'block', px: 2, pt: 2, color: '#98a2b3' }}>Administration</Typography>{management.map((item) => <ListItemButton key={item.path} component={NavLink} to={item.path} onClick={() => setOpen(false)} sx={{ borderRadius: 1, mb: .25, color: 'inherit', '&.active': { bgcolor: '#194185', color: 'white' } }}><ListItemIcon sx={{ color: 'inherit', minWidth: 38 }}>{item.icon}</ListItemIcon><ListItemText primary={item.label}/></ListItemButton>)}</List><Box sx={{ p: 2, borderTop: '1px solid #344054' }}><Stack direction="row" alignItems="center" spacing={1.5}><Avatar sx={{ width: 34, height: 34, bgcolor: '#155eef' }}>{session?.user.display_name?.[0] ?? 'U'}</Avatar><Box sx={{ minWidth: 0, flex: 1 }}><Typography noWrap variant="body2" sx={{ color: 'white' }}>{session?.user.display_name}</Typography><Typography noWrap variant="caption">{session?.user.email}</Typography></Box><IconButton aria-label="Log out" onClick={signOut} sx={{ color: '#98a2b3' }}><Logout fontSize="small"/></IconButton></Stack></Box></Box>
  return <Box sx={{ display: 'flex', minHeight: '100vh' }}>{mobile ? <Drawer open={open} onClose={() => setOpen(false)} PaperProps={{ sx: { bgcolor: '#101828' } }}>{content}</Drawer> : <Box component="nav">{content}</Box>}<Box sx={{ flex: 1, minWidth: 0 }}><AppBar position="sticky" color="inherit" elevation={0} sx={{ borderBottom: '1px solid #eaecf0' }}><Toolbar><IconButton onClick={() => setOpen(true)} sx={{ mr: 1, display: { md: 'none' } }}><Menu/></IconButton><Typography variant="body2" color="text.secondary" sx={{ flex: 1 }}>Workspace / <strong style={{ color: '#101828' }}>{current.label}</strong></Typography><ProjectSelect/><Chip icon={<Security/>} label="Protected session" size="small" variant="outlined" color="success" sx={{ ml: 2 }}/></Toolbar></AppBar><Box component="main" sx={{ p: { xs: 2, md: 4 }, maxWidth: 1600, mx: 'auto' }}><Routes><Route path="/" element={<DashboardPage/>}/><Route path="/projects" element={<ProjectsPage/>}/><Route path="/requirements" element={<RequirementsPage/>}/><Route path="/work-items" element={<WorkItemsPage/>}/><Route path="/architecture" element={<ArchitecturePage/>}/><Route path="/planning" element={<PlanningPage/>}/><Route path="/change-sets" element={<ChangeSetsPage/>}/><Route path="/design" element={<DesignPage/>}/><Route path="/acceptance" element={<AcceptancePage/>}/><Route path="/releases" element={<ReleasesPage/>}/><Route path="/deployment-control" element={<DeploymentControlPage/>}/><Route path="/repository" element={<RepositoryPage/>}/><Route path="/secrets" element={<SecretsPage/>}/><Route path="/sandbox" element={<SandboxPage/>}/><Route path="/operations" element={<OperationsPage/>}/><Route path="/gates" element={<GatesPage/>}/><Route path="/approvals" element={<ApprovalsPage/>}/><Route path="/login" element={<Navigate to="/"/>}/>{[...nav.slice(1).filter((item) => !['/projects', '/requirements', '/work-items', '/architecture', '/planning', '/design', '/releases', '/repository', '/secrets', '/sandbox', '/operations', '/gates'].includes(item.path)), ...management].map((item) => <Route key={item.path} path={`${item.path}/*`} element={<ResourcePage title={item.label} path={item.path}/>}/>)}</Routes></Box></Box></Box>
}

function DashboardPage() { const { session } = useAuth(); return <><PageHeader title={`Good to see you, ${session?.user.display_name?.split(' ')[0] ?? 'there'}`} description="A clear view of delivery health, approvals, and the next actions in your workspace." action={<Button variant="contained" startIcon={<Add/>} href="/projects">Create project</Button>}/><Stack direction={{ xs: 'column', md: 'row' }} spacing={2} sx={{ mb: 3 }}>{[['Open approvals', '0', 'No pending decisions'], ['Active agent runs', '0', 'All workers available'], ['Release health', 'Ready', 'No active incidents'], ['Audit integrity', 'Verified', 'Chain is healthy']].map(([label, value, sub]) => <Card key={label} sx={{ flex: 1 }}><CardContent><Typography color="text.secondary" variant="body2">{label}</Typography><Typography variant="h5" sx={{ mt: 1 }}>{value}</Typography><Typography variant="caption" color="text.secondary">{sub}</Typography></CardContent></Card>)}</Stack><Stack direction={{ xs: 'column', lg: 'row' }} spacing={3}><Card sx={{ flex: 1 }}><CardContent><Typography variant="h6">Recommended next actions</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>Your workspace is ready. Start by creating a project or review the current operational health.</Typography><Stack direction="row" spacing={1} sx={{ mt: 3 }}><Button variant="outlined" href="/projects">View projects</Button><Button variant="outlined" href="/operations">Open operations</Button></Stack></CardContent></Card><Card sx={{ flex: 1 }}><CardContent><Typography variant="h6">Delivery lifecycle</Typography><Stack spacing={2} sx={{ mt: 2 }}>{['Requirements', 'Architecture', 'Plan & implement', 'Design acceptance', 'Release & deploy'].map((step, i) => <Stack direction="row" spacing={2} alignItems="center" key={step}><Chip label={i + 1} color={i === 0 ? 'primary' : 'default'} size="small"/><Typography variant="body2">{step}</Typography><Typography variant="caption" color="text.secondary" sx={{ ml: 'auto !important' }}>{i === 0 ? 'Start here' : 'Awaiting project'}</Typography></Stack>)}</Stack></CardContent></Card></Stack></> }

function PageHeader({ title, description, action }: { title: string; description: string; action?: ReactNode }) { return <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }} sx={{ mb: 4 }}><Box sx={{ flex: 1 }}><Typography component="h1" variant="h4">{title}</Typography><Typography color="text.secondary" sx={{ mt: 1 }}>{description}</Typography></Box>{action}</Stack> }
function ResourcePage({ title, path }: { title: string; path: string }) { const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const resource = title.toLowerCase(); const description = `Manage ${resource} with organization-scoped controls, lifecycle state, evidence, and audit history.`; const runCheck = async () => { setBusy(true); try { await api('/api/v1/ping'); setMessage('API connection verified.'); } catch (e) { setMessage(e instanceof ApiError ? `${e.message} (${e.status})` : 'The API is unavailable.'); } finally { setBusy(false) } }; return <><PageHeader title={title} description={description} action={<Button variant="contained" startIcon={<Add/>}>New {resource.endsWith('s') ? resource.slice(0, -1) : resource}</Button>}/><Paper sx={{ p: { xs: 2, md: 4 } }}><Stack spacing={3} alignItems="flex-start"><Stack direction="row" spacing={1} alignItems="center"><Chip label="Workspace scoped" color="primary" variant="outlined"/><Chip label="Backend authorization required" variant="outlined"/></Stack><Box><Typography variant="h6">{title} workspace</Typography><Typography color="text.secondary" sx={{ mt: 1, maxWidth: 720 }}>This area is connected to the botq control plane. Records, transitions, approvals, evidence, and destructive actions are governed by the backend policy for the selected organization and project.</Typography></Box><Divider flexItem/><Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}><Button variant="outlined" onClick={runCheck} startIcon={busy ? <CircularProgress size={16}/> : <Dns/>}>Check API status</Button><Button variant="text" href="/openapi.json" target="_blank" rel="noopener noreferrer">View API contract</Button></Stack>{message && <Alert severity={message.includes('verified') ? 'success' : 'error'}>{message}</Alert>}<Typography variant="caption" color="text.secondary">Route: {path} · Sensitive values are never shown in this interface.</Typography></Stack></Paper><Snackbar open={false} message=""/></> }

export function App() { return <Routes><Route path="/login" element={<Login/>}/><Route path="/auth/callback" element={<Navigate to="/" replace/>}/><Route path="/preview-control" element={<Guard><PreviewControlPage/></Guard>}/><Route path="/organization/*" element={<Guard><Box component="main"><FeatureGate flag="organizationAdministration"><OrganizationPage/></FeatureGate></Box></Guard>}/><Route path="/settings/*" element={<Guard><Box component="main"><FeatureGate flag="organizationAdministration"><OrganizationPage/></FeatureGate></Box></Guard>}/><Route path="/projects/:projectId" element={<Guard><Box component="main"><ProjectDetailPage/></Box></Guard>}/><Route path="/architecture/:architectureId" element={<Guard><Box component="main"><ArchitectureDetailPage/></Box></Guard>}/><Route path="/requirements/:baselineId" element={<Guard><Box component="main"><RequirementDetailPage/></Box></Guard>}/><Route path="/work-items/:workItemId" element={<Guard><Box component="main"><WorkItemDetailPage/></Box></Guard>}/><Route path="/plans/:planId" element={<Guard><Box component="main"><PlanDetailPage/></Box></Guard>}/><Route path="/agent-runs/:runId" element={<Guard><Box component="main"><AgentRunDetailPage/></Box></Guard>}/><Route path="/releases/:releaseId" element={<Guard><Box component="main"><ReleaseDetailPage/></Box></Guard>}/><Route path="/deployments/:deploymentId" element={<Guard><Box component="main"><DeploymentDetailPage/></Box></Guard>}/><Route path="/traceability" element={<Guard><TraceabilityPage/></Guard>}/><Route path="/operations/control" element={<Guard><FeatureGate flag="advancedOperations"><OperationsControlPage/></FeatureGate></Guard>}/><Route path="*" element={<Guard><Shell/></Guard>}/></Routes> }
